class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    def to_fahrenheit(self):
        return self.celsius * 9 / 5 + 32

    def describe(self):
        f = self.to_fahrenheit()
        return f"{self.celsius}C is {f}F"

t = Temperature(100)
print(t.to_fahrenheit())
print(t.describe())
print(Temperature(0).describe())

